# Lesson 6: Functions & Reusable Code

def calculate_bmi(weight_kg, height_m):
    """Calculates Body Mass Index (BMI) and category."""
    bmi = weight_kg / (height_m ** 2)
    if bmi < 18.5:
        category = "Underweight"
    elif bmi < 25:
        category = "Normal weight"
    elif bmi < 30:
        category = "Overweight"
    else:
        category = "Obese"
    return round(bmi, 1), category

def factorial(n):
    """Calculates n! (1 * 2 * ... * n)."""
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

num = int(input("Enter a number to compute its factorial (e.g. 5): "))
print(f"{num}! = {factorial(num)}")

