# Interactive Bank ATM Simulator with while loop + input()
balance = 1000.0
print("🏦 Welcome to PyBank Interactive ATM")

while True:
    print(f"\nCurrent Balance: ₹{balance:.2f}")
    print("1. Deposit  |  2. Withdraw  |  3. Exit")
    choice = input("Choose an option (1/2/3): ").strip()

    if choice == "1":
        amt = float(input("Enter deposit amount: ₹"))
        if amt > 0:
            balance += amt
            print(f"✅ Deposited ₹{amt:.2f}")
    elif choice == "2":
        amt = float(input("Enter withdrawal amount: ₹"))
        if amt > balance:
            print("⚠️ Insufficient funds!")
        elif amt > 0:
            balance -= amt
            print(f"✅ Withdrew ₹{amt:.2f}")
    elif choice == "3":
        print("Thank you for banking with PyBank! 👋")
        break
    else:
        print("⚠️ Invalid option, please type 1, 2, or 3.")
